CREATE TABLE budgets(id TEXT PRIMARY KEY, name TEXT NOT NULL, period_type TEXT NOT NULL DEFAULT 'monthly' CHECK(period_type='monthly'),currency TEXT NOT NULL,start_date TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE budget_lines(budget_id TEXT NOT NULL REFERENCES budgets(id) ON DELETE CASCADE,category_id TEXT NOT NULL REFERENCES categories(id),limit_micros INTEGER NOT NULL CHECK(limit_micros>=0 AND limit_micros<=9007199254740991),PRIMARY KEY(budget_id,category_id));
CREATE UNIQUE INDEX active_budget_currency ON budgets(currency) WHERE active=1;
CREATE TABLE goals(id TEXT PRIMARY KEY,name TEXT NOT NULL,type TEXT NOT NULL CHECK(type IN ('savings','emergency_fund','debt_reduction','custom')),target_amount_micros INTEGER NOT NULL CHECK(target_amount_micros>0),current_amount_micros INTEGER NOT NULL,currency TEXT NOT NULL,target_date TEXT,linked_account_id TEXT REFERENCES accounts(id) ON DELETE SET NULL,status TEXT NOT NULL DEFAULT 'active');
CREATE TABLE recurring_series(id TEXT PRIMARY KEY,canonical_merchant TEXT NOT NULL,account_id TEXT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,category_id TEXT NOT NULL REFERENCES categories(id),currency TEXT NOT NULL,frequency TEXT NOT NULL,typical_amount_micros INTEGER NOT NULL,previous_amount_micros INTEGER,monthly_amount_micros INTEGER NOT NULL,amount_variance REAL NOT NULL,next_expected_date TEXT NOT NULL,confidence REAL NOT NULL,status TEXT NOT NULL,first_seen TEXT NOT NULL,last_seen TEXT NOT NULL,observations INTEGER NOT NULL);
CREATE INDEX recurring_next ON recurring_series(next_expected_date);
CREATE TABLE anomalies(id TEXT PRIMARY KEY,transaction_id TEXT REFERENCES transactions(id) ON DELETE CASCADE,kind TEXT NOT NULL,currency TEXT NOT NULL,amount_micros INTEGER NOT NULL,date TEXT NOT NULL,description TEXT NOT NULL);
